// ===== DASHBOARD METRICS CALCULATOR v2 =====
// Pinagsasama: Customer Requests + Agent Directory + Workflow Errors
// Output: buong JSON para sa 4-page dashboard

const isReal = (o) => o && Object.keys(o).some(k => k !== 'id' && k !== 'createdTime');

const records = $('Get Customer Requests').all().map(i => i.json).filter(isReal);
const agentRows = $('Get Agent Directory').all().map(i => i.json).filter(isReal);
const errorRows = $input.all().map(i => i.json).filter(isReal);

const num = (v) => (typeof v === 'number' ? v : parseFloat(v) || 0);

/* ---------- Summary base ---------- */
const total = records.length;
const autoHandled = records.filter(r => r.Status === 'Auto-Handled').length;
const notified = records.filter(r => r.Status === 'Notified').length;
const needsReview = records.filter(r => r['Needs Human Review'] === true).length;
const avgConfidence = total
  ? Math.round((records.reduce((s, r) => s + num(r.Confidence), 0) / total) * 10) / 10
  : 0;

/* ---------- Response time (Received At -> Processed At) ---------- */
const respTimes = [];
for (const r of records) {
  const a = new Date(r['Received At']);
  const b = new Date(r['Processed At']);
  if (!isNaN(a.getTime()) && !isNaN(b.getTime()) && b >= a) {
    respTimes.push((b - a) / 60000);
  }
}
const avgResponseMinutes = respTimes.length
  ? Math.round((respTimes.reduce((s, v) => s + v, 0) / respTimes.length) * 10) / 10
  : null;

/* ---------- Time saved (6 mins per auto-handled reply) ---------- */
const timeSavedHours = Math.round(((autoHandled * 6) / 60) * 10) / 10;

/* ---------- Weekly buckets (weeks starting Monday) ---------- */
const weekMap = {};
for (const r of records) {
  const d = new Date(r['Received At']);
  if (isNaN(d.getTime())) continue;
  const dayIndex = (d.getDay() + 6) % 7;
  const monday = new Date(d);
  monday.setDate(d.getDate() - dayIndex);
  const key = monday.toISOString().slice(0, 10);
  if (!weekMap[key]) {
    weekMap[key] = { weekStart: key, total: 0, autoHandled: 0, notified: 0, confSum: 0 };
  }
  weekMap[key].total++;
  if (r.Status === 'Auto-Handled') weekMap[key].autoHandled++;
  if (r.Status === 'Notified') weekMap[key].notified++;
  weekMap[key].confSum += num(r.Confidence);
}
const weeklyTrend = Object.values(weekMap)
  .sort((a, b) => a.weekStart.localeCompare(b.weekStart))
  .map(w => ({
    weekStart: w.weekStart,
    total: w.total,
    autoHandled: w.autoHandled,
    notified: w.notified,
    avgConfidence: Math.round((w.confSum / w.total) * 10) / 10
  }));

/* ---------- Week-over-week deltas (huwag isama ang kasalukuyang linggo) ---------- */
const nowMonday = (() => {
  const d = new Date();
  const dayIndex = (d.getDay() + 6) % 7;
  d.setDate(d.getDate() - dayIndex);
  return d.toISOString().slice(0, 10);
})();
let cmpWeeks = weeklyTrend.filter(w => w.weekStart !== nowMonday);
if (cmpWeeks.length < 2) cmpWeeks = weeklyTrend;
let weekOverWeek = null;
if (cmpWeeks.length >= 2) {
  const last = cmpWeeks[cmpWeeks.length - 1];
  const prev = cmpWeeks[cmpWeeks.length - 2];
  const pct = (a, b) => (b ? Math.round(((a - b) / b) * 1000) / 10 : null);
  weekOverWeek = {
    latestWeek: last.weekStart,
    previousWeek: prev.weekStart,
    totalPct: pct(last.total, prev.total),
    autoHandledPct: pct(last.autoHandled, prev.autoHandled),
    notifiedPct: pct(last.notified, prev.notified),
    avgConfidenceDelta: Math.round((last.avgConfidence - prev.avgConfidence) * 10) / 10
  };
}

/* ---------- Category breakdown ---------- */
const catMap = {};
for (const r of records) {
  const c = r.Category || 'Uncategorized';
  if (!catMap[c]) {
    catMap[c] = { category: c, total: 0, autoHandled: 0, notified: 0, confidenceSum: 0 };
  }
  catMap[c].total++;
  if (r.Status === 'Auto-Handled') catMap[c].autoHandled++;
  if (r.Status === 'Notified') catMap[c].notified++;
  catMap[c].confidenceSum += num(r.Confidence);
}
const categoryBreakdown = Object.values(catMap)
  .map(c => ({
    category: c.category,
    total: c.total,
    autoHandled: c.autoHandled,
    notified: c.notified,
    avgConfidence: Math.round((c.confidenceSum / c.total) * 10) / 10
  }))
  .sort((a, b) => b.total - a.total);

/* ---------- Full request list (para sa Requests page) ---------- */
const allRequests = [...records]
  .sort((a, b) => new Date(b['Received At']) - new Date(a['Received At']))
  .map(r => {
    const a = new Date(r['Received At']);
    const b = new Date(r['Processed At']);
    const rm = (!isNaN(a.getTime()) && !isNaN(b.getTime()) && b >= a)
      ? Math.round(((b - a) / 60000) * 10) / 10
      : null;
    return {
      sender: r['Sender Name'] || r['Sender Email'] || 'Unknown',
      senderEmail: r['Sender Email'] || '',
      subject: r.Subject || '',
      body: r.Body || '',
      category: r.Category || '',
      status: r.Status || '',
      confidence: num(r.Confidence),
      needsHumanReview: r['Needs Human Review'] === true,
      aiReasoning: r['AI Reasoning'] || '',
      draftResponse: r['Draft Response'] || '',
      assignedTo: r['Assigned To'] || '',
      receivedAt: r['Received At'] || '',
      processedAt: r['Processed At'] || '',
      responseMinutes: rm
    };
  });
const recentRequests = allRequests.slice(0, 8);

/* ---------- Agents (join Agent Directory + handled counts) ---------- */
const handledBy = {};
for (const r of records) {
  const a = r['Assigned To'] || 'Unassigned';
  handledBy[a] = (handledBy[a] || 0) + 1;
}
const agents = agentRows
  .map(a => {
    const name = a['Agent Name'] || 'Unknown';
    return {
      name: name,
      specialty: a['Category'] || '',
      email: a['Agent Email'] || '',
      available: a['Is Available'] === true,
      backup: a['Backup Agent'] || '',
      handled: handledBy[name] || 0
    };
  })
  .sort((x, y) => y.handled - x.handled);

const agentBreakdown = Object.entries(handledBy)
  .map(([agent, count]) => ({ agent: agent, total: count }))
  .sort((a, b) => b.total - a.total);

/* ---------- System health (Workflow Errors) ---------- */
const errSorted = [...errorRows].sort(
  (a, b) => new Date(b['Timestamp']) - new Date(a['Timestamp'])
);
const resolvedCount = errorRows.filter(e => e.Resolved === true).length;
const toErr = (e) => ({
  timestamp: e['Timestamp'] || '',
  nodeName: e['Node Name'] || '',
  errorMessage: e['Error Message'] || '',
  resolved: e.Resolved === true
});
const systemHealth = {
  totalErrors: errorRows.length,
  resolvedErrors: resolvedCount,
  unresolvedErrors: errorRows.length - resolvedCount,
  lastError: errSorted.length ? toErr(errSorted[0]) : null,
  recentErrors: errSorted.slice(0, 5).map(toErr)
};

/* ---------- Output ---------- */
return [
  {
    json: {
      generatedAt: new Date().toISOString(),
      summary: {
        totalRequests: total,
        autoHandled: autoHandled,
        autoHandledPercent: total ? Math.round((autoHandled / total) * 1000) / 10 : 0,
        notified: notified,
        needsHumanReview: needsReview,
        avgConfidence: avgConfidence,
        avgResponseMinutes: avgResponseMinutes,
        timeSavedHours: timeSavedHours,
        weekOverWeek: weekOverWeek
      },
      categoryBreakdown: categoryBreakdown,
      agentBreakdown: agentBreakdown,
      weeklyTrend: weeklyTrend,
      recentRequests: recentRequests,
      allRequests: allRequests,
      agents: agents,
      systemHealth: systemHealth
    }
  }
];
